package com.bananalab.lite;
import java.util.*;import java.util.regex.*;
/** Deliberately constrained Java source, not a general untrusted-code sandbox. */
final class JavaPatchPolicy{
 static final String BASE="package com.bananalab.patch;\npublic final class BananaBehavior {\n public static String celebration() { return \"baila,saluda,salta\"; }\n public static float kissGap() { return 0.0f; }\n public static String rewrite(String input) { return input; }\n}\n";
 static final String LITERAL="\"(?:[^\"\\\\\\r\\n]|\\\\[\"\\\\nrt])*\"";
 static void validate(String raw)throws Exception{if(raw.length()>12000||raw.contains("\\u")||raw.contains("/*")||raw.contains("//"))throw new IllegalArgumentException("La clase admite hasta12000 caracteres, sin comentarios ni escapes Unicode.");String source=raw.replaceAll("\\s+"," ").trim();Matcher header=Pattern.compile("^package com\\.bananalab\\.patch; public final class BananaBehavior \\{(.*)\\}$").matcher(source);if(!header.matches())throw new IllegalArgumentException("Conservá el paquete y la clase BananaBehavior del ejemplo.");String body=header.group(1);Matcher celebration=Pattern.compile("public static String celebration\\(\\) \\{ return ("+LITERAL+"); \\}").matcher(body);if(!celebration.find())throw new IllegalArgumentException("celebration debe devolver una cadena literal.");String recipe=celebration.group(1).substring(1,celebration.group(1).length()-1);sequence(recipe);body=celebration.replaceFirst("");Matcher gap=Pattern.compile("public static float kissGap\\(\\) \\{ return ([0-9]+(?:\\.[0-9]+)?f?); \\}").matcher(body);if(!gap.find())throw new IllegalArgumentException("kissGap debe devolver un número literal entre0 y4.");float number=Float.parseFloat(gap.group(1).replace("f",""));if(number<0||number>4)throw new IllegalArgumentException("Separación fuera de0 a4 unidades.");body=gap.replaceFirst("");Matcher rewrite=Pattern.compile("public static String rewrite\\(String input\\) \\{ (.*) \\}").matcher(body.trim());if(!rewrite.matches())throw new IllegalArgumentException("Solo se admite el método rewrite del ejemplo.");String statements=rewrite.group(1);Pattern condition=Pattern.compile("^if \\(input\\.equals\\(("+LITERAL+")\\)\\) return ("+LITERAL+"); ");int rules=0;while(statements.startsWith("if ")){Matcher m=condition.matcher(statements);if(!m.find()||++rules>8)throw new IllegalArgumentException("rewrite admite hasta ocho if de igualdad literal.");String replacement=m.group(2).substring(1,m.group(2).length()-1);if(!replacement.matches("(?s)^(?:continua con|crea|agrega|pone|cambia|dibuja) [a-zA-ZáéíóúñÁÉÍÓÚÑ0-9 ,;]+$"))throw new IllegalArgumentException("La reescritura debe ser una orden de escena acotada.");statements=statements.substring(m.end());}if(!statements.equals("return input;"))throw new IllegalArgumentException("rewrite debe terminar con return input; y no puede ejecutar otras operaciones.");}
 static String[] sequence(String value){String[] parts=value.split(",");if(parts.length<1||parts.length>8)throw new IllegalArgumentException("La celebración admite de uno a ocho movimientos.");for(String p:parts)if(!p.matches("baila|salta|saluda|gira|aplaude|espera"))throw new IllegalArgumentException("Movimiento Java no admitido: "+p);return parts;}
}
